from argon2 import PasswordHasher
from argon2.exceptions import VerifyMismatchError

class Argon2PasswordStore:
    def __init__(self, pepper):
        self._pepper = pepper
        self._users = {}
        self._ph = PasswordHasher()
        # Create a dummy hash to use for non‑existent user lookups
        self._dummy_hash = self._ph.hash('dummy')

    def register(self, username, password):
        if username in self._users:
            raise ValueError('User already exists')
        combined = self._pepper + password
        hashed = self._ph.hash(combined)
        self._users[username] = hashed
        return True

    def login(self, username, password):
        stored_hash = self._users.get(username)
        if stored_hash is None:
            # Use dummy to avoid timing difference
            try:
                self._ph.verify(self._dummy_hash, 'dummy')
            except:
                pass
            return False
        combined = self._pepper + password
        try:
            self._ph.verify(stored_hash, combined)
            return True
        except VerifyMismatchError:
            return False
